INSERT INTO commerce_products (product_id, name, classification, unit_price_cents, unit_price_approved, status, oba_product_id, editorial_type, price_source_cents, google_description, hotplate_description, website_description, social_description, date_added, featured_priority, ingredients, allergens, reference_availability, slug, image_path, product_kind) VALUES ('cinna-cookie-swirl', 'Cinna’ Cookie Swirl', 'specialty', 500, 0, 'active', 'OBA-020', 'Specialty', 500, 'A soft cinnamon brown sugar cookie stuffed with creamy cinnamon filling and finished with sweet cream cheese glaze for a rich, cinnamon-roll-inspired bite.', 'A soft cinnamon brown sugar cookie stuffed with creamy cinnamon filling and finished with a sweet cream cheese glaze.', 'Cinnamon Roll, Meet Cookie.
Cinna’ Cookie Swirl takes everything cozy about a cinnamon roll and bakes it into a soft OBA cookie. Cinnamon and brown sugar bring warm, buttery sweetness to the cookie before a creamy cinnamon filling adds a rich surprise in the center.

A sweet cream cheese glaze finishes everything on top, bringing that familiar cinnamon-roll finish to every bite. Soft, spiced, creamy, and made for anyone who thinks the middle of the cinnamon roll is the best part.', '', '2026-09-19', 1, '', '', 'Available', 'cinna-cookie-swirl', '', 'cookie') ON CONFLICT(product_id) DO UPDATE SET oba_product_id=excluded.oba_product_id, name=excluded.name, editorial_type=excluded.editorial_type, price_source_cents=excluded.price_source_cents, google_description=excluded.google_description, hotplate_description=excluded.hotplate_description, website_description=excluded.website_description, social_description=excluded.social_description, date_added=excluded.date_added, featured_priority=excluded.featured_priority, ingredients=excluded.ingredients, allergens=excluded.allergens, reference_availability=excluded.reference_availability, slug=excluded.slug, image_path=excluded.image_path, product_kind=excluded.product_kind, updated_at=CURRENT_TIMESTAMP;
INSERT INTO commerce_products (product_id, name, classification, unit_price_cents, unit_price_approved, status, oba_product_id, editorial_type, price_source_cents, google_description, hotplate_description, website_description, social_description, date_added, featured_priority, ingredients, allergens, reference_availability, slug, image_path, product_kind) VALUES ('spiced-cocoa', 'Spiced Cocoa', 'specialty', 500, 0, 'active', 'OBA-021', 'Specialty', 500, 'A rich Mexican hot chocolate cookie with cocoa, chocolate chips, warm cinnamon, marshmallows, and a subtle touch of cayenne for a cozy chocolate bite with a little kick.', 'A rich Mexican hot chocolate cookie made with cocoa, warm cinnamon, chocolate chips, marshmallows, and a subtle touch of cayenne pepper.', 'Hot Cocoa With a Little Kick.
Spiced Cocoa turns Mexican hot chocolate into a thick, soft OBA cookie. Rich cocoa and melty chocolate chips build the chocolate base, while warm cinnamon gives every bite its cozy, spiced character.

Marshmallows bring the hot-cocoa sweetness before a subtle touch of cayenne sneaks in with a little warmth at the finish. Chocolatey, cozy, lightly spiced, and just adventurous enough to keep things interesting.', '', '2026-09-20', 2, '', '', 'Available', 'spiced-cocoa', '', 'cookie') ON CONFLICT(product_id) DO UPDATE SET oba_product_id=excluded.oba_product_id, name=excluded.name, editorial_type=excluded.editorial_type, price_source_cents=excluded.price_source_cents, google_description=excluded.google_description, hotplate_description=excluded.hotplate_description, website_description=excluded.website_description, social_description=excluded.social_description, date_added=excluded.date_added, featured_priority=excluded.featured_priority, ingredients=excluded.ingredients, allergens=excluded.allergens, reference_availability=excluded.reference_availability, slug=excluded.slug, image_path=excluded.image_path, product_kind=excluded.product_kind, updated_at=CURRENT_TIMESTAMP;
