No pile of toppings needed—just brown sugar, real maple, and a soft buttery center doing exactly what they came here to do.', '', '2026-09-22', 4, '', '', 'Available', 'plain-maple', '', 'cookie') ON CONFLICT(product_id) DO UPDATE SET oba_product_id=excluded.oba_product_id, name=excluded.name, editorial_type=excluded.editorial_type, price_source_cents=excluded.price_source_cents, google_description=excluded.google_description, hotplate_description=excluded.hotplate_description, website_description=excluded.website_description, social_description=excluded.social_description, date_added=excluded.date_added, featured_priority=excluded.featured_priority, ingredients=excluded.ingredients, allergens=excluded.allergens, reference_availability=excluded.reference_availability, slug=excluded.slug, image_path=excluded.image_path, product_kind=excluded.product_kind, updated_at=CURRENT_TIMESTAMP;
