Inside is a gooey s''mores center, while a graham cracker base and toasted marshmallow finish bring the full campfire effect. It is rich, messy, melty, and built to feel like a s''more turned into an oversized OBA cookie.', 'A gooey brown butter s''mores cookie packed with chocolate & marshmallow, baked on graham cracker and topped with toasted marshmallow.', '2026-07-18', 9, '', '', 'Unavailable', 'campfire-crunch', 'images/campfire-crunch.jpg', 'cookie') ON CONFLICT(product_id) DO UPDATE SET oba_product_id=excluded.oba_product_id, name=excluded.name, editorial_type=excluded.editorial_type, price_source_cents=excluded.price_source_cents, google_description=excluded.google_description, hotplate_description=excluded.hotplate_description, website_description=excluded.website_description, social_description=excluded.social_description, date_added=excluded.date_added, featured_priority=excluded.featured_priority, ingredients=excluded.ingredients, allergens=excluded.allergens, reference_availability=excluded.reference_availability, slug=excluded.slug, image_path=excluded.image_path, product_kind=excluded.product_kind, updated_at=CURRENT_TIMESTAMP;
INSERT INTO commerce_products (product_id, name, classification, unit_price_cents, unit_price_approved, status, oba_product_id, editorial_type, price_source_cents, google_description, hotplate_description, website_description, social_description, date_added, featured_priority, ingredients, allergens, reference_availability, slug, image_path, product_kind) VALUES ('biscoff-lava-crunch', 'Biscoff Lava Crunch', 'regular', 400, 0, 'active', 'OBA-003', 'Fan Favorite', 400, 'A soft Biscoff cookie stuffed with creamy cookie butter and topped with Biscoff drizzle, butterscotch chips, and crunchy cookie crumbles for a rich, caramelized cookie-butter bite.', 'Biscoff cookie stuffed with creamy cookie butter and topped with Biscoff drizzle, butterscotch chips, and crunchy cookie crumbles.', 'Cookie Butter, Turned All the Way Up.
