A Biscoff drizzle, butterscotch chips, and crunchy cookie crumbles finish the top, giving every bite a mix of soft cookie, creamy filling, and crisp spiced-cookie crunch.', 'Biscoff cookie stuffed with creamy cookie butter and topped with Biscoff drizzle, butterscotch chips, and crunchy cookie crumbles.', '2026-06-07', 10, '', '', 'Unavailable', 'biscoff-lava-crunch', 'images/biscoff-lava-crunch.jpg', 'cookie') ON CONFLICT(product_id) DO UPDATE SET oba_product_id=excluded.oba_product_id, name=excluded.name, editorial_type=excluded.editorial_type, price_source_cents=excluded.price_source_cents, google_description=excluded.google_description, hotplate_description=excluded.hotplate_description, website_description=excluded.website_description, social_description=excluded.social_description, date_added=excluded.date_added, featured_priority=excluded.featured_priority, ingredients=excluded.ingredients, allergens=excluded.allergens, reference_availability=excluded.reference_availability, slug=excluded.slug, image_path=excluded.image_path, product_kind=excluded.product_kind, updated_at=CURRENT_TIMESTAMP;
